window.__qzParts=window.__qzParts||{};window.__qzParts.tin=[{"p":"Bộ phận nào của máy tính dùng để hiển thị hình ảnh và chữ?","o":["Màn hình","Bàn phím","Chuột máy tính","Thân máy"],"a":"Màn hình","h":"Bộ phận trông giống chiếc ti vi.","e":"Màn hình hiển thị hình ảnh, chữ và video để em nhìn thấy.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Bộ phận nào của máy tính chứa các mạch điện và được ví như bộ não xử lí thông tin?","o":["Thân máy","Màn hình","Chuột máy tính","Loa"],"a":"Thân máy","h":"Đây là chiếc hộp lớn nhất trong các bộ phận rời của máy tính để bàn.","e":"Thân máy chứa bộ xử lí trung tâm, được ví như bộ não của máy tính.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Để nhập chữ và số vào máy tính, em dùng bộ phận nào?","o":["Bàn phím","Màn hình","Chuột máy tính","Thân máy"],"a":"Bàn phím","h":"Bộ phận có rất nhiều phím chữ và phím số.","e":"Bàn phím có các phím chữ, phím số để em gõ vào máy tính.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Thao tác nháy đúp chuột là làm gì?","o":["Nhấn nút trái chuột hai lần liên tiếp thật nhanh","Nhấn giữ chuột thật lâu","Kéo chuột đi thật xa","Nhấn nút phải chuột một lần"],"a":"Nhấn nút trái chuột hai lần liên tiếp thật nhanh","h":"Thao tác này gồm hai lần nhấn chuột rất gần nhau.","e":"Nháy đúp là nhấn nút trái chuột hai lần liên tiếp thật nhanh, thường dùng để mở phần mềm.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Khi ngồi học với máy tính, tư thế nào là đúng?","o":["Ngồi thẳng lưng, mắt cách màn hình vừa phải","Ghé sát mặt vào màn hình","Ngồi cong lưng, cúi sát bàn phím","Nằm dài ra ghế nhìn màn hình"],"a":"Ngồi thẳng lưng, mắt cách màn hình vừa phải","h":"Tư thế đúng giúp em bảo vệ mắt và cột sống.","e":"Ngồi thẳng lưng và giữ khoảng cách vừa phải với màn hình giúp em bảo vệ mắt và cột sống.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Phím nào sau đây thuộc hàng phím cơ sở trên bàn phím?","o":["Phím A","Phím Q","Phím Z","Phím P"],"a":"Phím A","h":"Hàng phím cơ sở là hàng phím ở giữa, nơi em đặt tay khi bắt đầu gõ.","e":"Hàng phím cơ sở gồm các phím A, S, D, F, G, H, J, K, L.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Việc nào sau đây giúp em an toàn khi dùng máy tính?","o":["Không chạm tay ướt vào dây điện và ổ cắm","Vừa ăn uống vừa gõ bàn phím","Để cốc nước ngay cạnh bàn phím","Tự ý tháo nắp thân máy ra xem"],"a":"Không chạm tay ướt vào dây điện và ổ cắm","h":"Hãy nghĩ đến nguy cơ từ điện và nước.","e":"Tay ướt chạm vào điện rất nguy hiểm, em cần giữ tay khô và tránh xa ổ cắm điện.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Thông tin nào sau đây em không nên chia sẻ cho người lạ?","o":["Mật khẩu và địa chỉ nhà của em","Tên bài hát em thích","Màu sắc em yêu thích","Môn học em thích nhất"],"a":"Mật khẩu và địa chỉ nhà của em","h":"Đó là những thông tin riêng tư chỉ em và gia đình biết.","e":"Mật khẩu, địa chỉ nhà, số điện thoại là thông tin cá nhân cần giữ kín.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Để di chuyển một biểu tượng trên màn hình đến vị trí khác, em dùng thao tác nào với chuột?","o":["Kéo thả","Nháy đúp","Nháy chuột phải","Lăn nút cuộn"],"a":"Kéo thả","h":"Em nhấn giữ chuột, đưa biểu tượng đi rồi buông ra.","e":"Kéo thả là nhấn giữ nút trái chuột, di chuyển chuột đến vị trí mới rồi thả ra.","t":"tin-cap1","l":"thu-thach"},{"p":"Em sắp xếp sách vở và đồ dùng gọn gàng, theo đúng chỗ để làm gì?","o":["Để dễ tìm khi cần dùng","Chỉ để trông cho đẹp mắt","Để được bạn bè khen","Để cất được nhiều đồ hơn"],"a":"Để dễ tìm khi cần dùng","h":"Giống như khi em tìm một quyển sách trong cặp đã sắp xếp ngăn nắp.","e":"Sắp xếp đồ vật theo trật tự giúp em tìm nhanh khi cần dùng.","t":"tin-cap1","l":"thu-thach"},{"p":"Để chơi trò chơi ghép hình trên máy tính, em cần mở gì?","o":["Một phần mềm trò chơi","Thân máy","Ổ cắm điện","Bàn học"],"a":"Một phần mềm trò chơi","h":"Trò chơi trên máy tính chạy nhờ một chương trình được cài sẵn.","e":"Trò chơi ghép hình là một phần mềm, em nháy đúp vào biểu tượng của nó để mở và chơi.","t":"tin-cap1","l":"thu-thach"},{"p":"Khi em di chuyển chuột trên mặt bàn, con trỏ chuột trên màn hình sẽ thế nào?","o":["Di chuyển theo","Đứng yên một chỗ","Biến mất","Quay tròn liên tục"],"a":"Di chuyển theo","h":"Con trỏ chuột luôn nghe theo chuyển động của chuột.","e":"Con trỏ chuột di chuyển theo đúng hướng em di chuyển chuột trên mặt bàn.","t":"tin-cap1","l":"thu-thach"},{"p":"Hai phím có gờ nhỏ trên hàng phím cơ sở, giúp em đặt tay đúng mà không cần nhìn, là phím nào?","o":["Phím F và phím J","Phím A và phím L","Phím G và phím H","Phím D và phím K"],"a":"Phím F và phím J","h":"Đó là hai phím dành cho hai ngón tay trỏ.","e":"Phím F và phím J có gờ nhỏ để em định vị hai ngón tay trỏ khi gõ phím.","t":"tin-cap1","l":"thu-thach"},{"p":"Em muốn mở một phần mềm từ màn hình nền (Desktop). Thao tác đúng là gì?","o":["Nháy đúp chuột vào biểu tượng của phần mềm","Nháy chuột một lần vào biểu tượng","Kéo biểu tượng của phần mềm đi chỗ khác","Nhấn nút phải chuột vào biểu tượng"],"a":"Nháy đúp chuột vào biểu tượng của phần mềm","h":"Hãy nhớ thao tác mở phần mềm đã học ở bài chuột máy tính.","e":"Trên màn hình nền, em nháy đúp chuột vào biểu tượng để mở phần mềm.","t":"tin-cap1","l":"kho"},{"p":"Sắp xếp các tệp và thư mục trong máy tính gọn gàng, theo từng nhóm có lợi ích gì?","o":["Giúp em tìm lại tệp nhanh và dễ dàng","Làm máy tính nặng hơn","Làm màn hình sáng hơn","Giúp chuột chạy nhanh hơn"],"a":"Giúp em tìm lại tệp nhanh và dễ dàng","h":"Lợi ích này giống với việc sắp xếp đồ dùng trong phòng của em.","e":"Giống như sắp xếp đồ dùng, sắp xếp tệp ngăn nắp giúp em tìm lại nhanh khi cần.","t":"tin-cap1","l":"kho"},{"p":"Phần cứng của máy tính là gì?","o":["Các bộ phận em có thể nhìn thấy và chạm vào được","Các chương trình chạy trong máy tính","Các trò chơi trên máy tính","Các trang web trên Internet"],"a":"Các bộ phận em có thể nhìn thấy và chạm vào được","h":"Hãy nghĩ đến màn hình, bàn phím và chuột.","e":"Phần cứng gồm các bộ phận vật lí như màn hình, bàn phím, chuột và thân máy.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Phần mềm của máy tính là gì?","o":["Các chương trình giúp máy tính làm việc theo yêu cầu của em","Chiếc hộp chứa các bộ phận máy tính","Sợi dây nối các bộ phận với nhau","Chiếc ghế em ngồi khi học"],"a":"Các chương trình giúp máy tính làm việc theo yêu cầu của em","h":"Phần mềm khác phần cứng ở chỗ em không chạm vào được.","e":"Phần mềm là các chương trình bên trong máy tính, em không sờ hay chạm vào được.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Vật nào sau đây là phần cứng của máy tính?","o":["Bàn phím","Phần mềm vẽ Paint","Phần mềm soạn thảo văn bản","Trò chơi trên máy tính"],"a":"Bàn phím","h":"Chỉ có một lựa chọn là vật thật em cầm được.","e":"Bàn phím là bộ phận vật lí nên thuộc phần cứng, các lựa chọn còn lại là phần mềm.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Internet là gì?","o":["Mạng máy tính khổng lồ kết nối các máy tính trên khắp thế giới","Một loại máy tính mới","Một trò chơi trực tuyến","Một phần mềm vẽ tranh"],"a":"Mạng máy tính khổng lồ kết nối các máy tính trên khắp thế giới","h":"Nhờ có Internet, em xem được thông tin từ rất xa.","e":"Internet kết nối hàng tỉ máy tính trên thế giới để các máy chia sẻ thông tin với nhau.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Thư mục trong máy tính dùng để làm gì?","o":["Chứa và sắp xếp các tệp cho gọn gàng","Để vẽ tranh","Để nghe nhạc","Để gõ văn bản"],"a":"Chứa và sắp xếp các tệp cho gọn gàng","h":"Thư mục giống như một ngăn tủ đựng đồ.","e":"Thư mục giúp em chứa và phân loại các tệp cho gọn gàng, dễ tìm.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Muốn gõ được tiếng Việt có dấu trên máy tính, em cần bật gì?","o":["Phần mềm hỗ trợ gõ tiếng Việt","Phần mềm vẽ tranh","Phần mềm trình chiếu","Phần mềm nghe nhạc"],"a":"Phần mềm hỗ trợ gõ tiếng Việt","h":"Bàn phím không tự tạo được dấu tiếng Việt nếu thiếu phần mềm này.","e":"Em cần bật phần mềm hỗ trợ gõ tiếng Việt thì mới gõ được chữ có dấu.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Sau khi soạn thảo văn bản xong, em cần làm gì để lần sau mở lại được?","o":["Lưu văn bản vào máy tính","Tắt máy ngay lập tức","Xoá hết văn bản vừa gõ","In văn bản ra giấy"],"a":"Lưu văn bản vào máy tính","h":"Việc này giúp bài làm của em không bị mất.","e":"Lưu văn bản giúp em giữ lại bài làm để xem và chỉnh sửa sau này.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Việc nào sau đây thể hiện em tôn trọng bản quyền?","o":["Không sao chép bài làm hay phần mềm của người khác khi chưa được phép","Sao chép tranh của bạn rồi nhận là của mình","Tải phần mềm lậu về dùng","Chép bài của bạn khi làm bài tập"],"a":"Không sao chép bài làm hay phần mềm của người khác khi chưa được phép","h":"Tôn trọng bản quyền nghĩa là tôn trọng công sức của người tạo ra sản phẩm.","e":"Tôn trọng bản quyền là không dùng sản phẩm của người khác khi chưa được cho phép.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Em muốn giới thiệu về trường mình trước lớp bằng các trang chiếu có chữ và hình ảnh. Phần mềm trình chiếu giúp em làm gì?","o":["Tạo các trang chiếu có chữ, hình ảnh để trình bày trước lớp","Chỉ dùng để nghe nhạc","Chỉ dùng để luyện gõ phím","Dùng để lưu trữ mọi tệp"],"a":"Tạo các trang chiếu có chữ, hình ảnh để trình bày trước lớp","h":"Hãy nhớ các buổi thuyết trình em từng xem trên lớp.","e":"Phần mềm trình chiếu giúp em tạo các trang chiếu sinh động để trình bày trước lớp.","t":"tin-cap1","l":"thu-thach"},{"p":"Khi đặt tên cho tệp, em nên đặt tên như thế nào?","o":["Tên gợi nhớ nội dung của tệp","Tên thật dài và khó hiểu","Tên không có nghĩa","Tên giống hệt nhau cho mọi tệp"],"a":"Tên gợi nhớ nội dung của tệp","h":"Tên tệp tốt giúp em nhận ra ngay tệp chứa gì.","e":"Đặt tên tệp gợi nhớ nội dung giúp em tìm lại tệp nhanh chóng.","t":"tin-cap1","l":"thu-thach"},{"p":"Muốn chèn một bức ảnh vào trang chiếu, em làm thế nào?","o":["Dùng lệnh chèn ảnh trong phần mềm trình chiếu rồi chọn ảnh","Vẽ lại bức ảnh bằng tay","In ảnh ra rồi dán lên màn hình","Không thể chèn ảnh vào trang chiếu"],"a":"Dùng lệnh chèn ảnh trong phần mềm trình chiếu rồi chọn ảnh","h":"Phần mềm trình chiếu có sẵn lệnh dành riêng cho việc đưa ảnh vào.","e":"Phần mềm trình chiếu có lệnh chèn ảnh, em chọn ảnh từ trong máy tính để đưa vào trang chiếu.","t":"tin-cap1","l":"thu-thach"},{"p":"Khi tìm thông tin trên Internet để làm bài tập, em nên làm gì?","o":["Gõ từ khoá ngắn gọn liên quan đến điều cần tìm","Gõ cả một đoạn văn thật dài vào ô tìm kiếm","Chỉ xem bất kì trang nào hiện ra đầu tiên","Sao chép mọi thứ tìm thấy vào bài làm"],"a":"Gõ từ khoá ngắn gọn liên quan đến điều cần tìm","h":"Từ khoá là những từ quan trọng nhất của điều em cần tìm.","e":"Dùng từ khoá ngắn gọn giúp máy tìm kiếm đưa ra kết quả đúng ý em hơn.","t":"tin-cap1","l":"thu-thach"},{"p":"Ví dụ nào sau đây là phần mềm?","o":["Phần mềm soạn thảo văn bản","Màn hình","Thân máy","Sợi dây cáp nối"],"a":"Phần mềm soạn thảo văn bản","h":"Phần mềm là chương trình, không phải vật em cầm được.","e":"Phần mềm soạn thảo là chương trình trong máy tính, các lựa chọn còn lại đều là phần cứng.","t":"tin-cap1","l":"thu-thach"},{"p":"Em có nhiều tệp ảnh chụp chuyến đi chơi của lớp. Cách sắp xếp nào hợp lí nhất?","o":["Tạo một thư mục riêng cho chuyến đi và đưa các ảnh vào đó","Để tất cả ảnh lẫn với mọi tệp khác","Đặt tất cả các ảnh cùng một tên","Xoá bớt ảnh cho đỡ rối"],"a":"Tạo một thư mục riêng cho chuyến đi và đưa các ảnh vào đó","h":"Hãy gom những tệp liên quan đến nhau vào cùng một chỗ.","e":"Gom các tệp liên quan vào một thư mục giúp em quản lí và tìm kiếm dễ dàng.","t":"tin-cap1","l":"kho"},{"p":"Bạn em bảo em chép lại một phần mềm học tập có bản quyền (phải mua mới được dùng) để mang về cài. Em nên làm gì?","o":["Không sao chép trái phép, chỉ dùng khi được phép hoặc nhờ người lớn mua bản quyền","Cứ chép về dùng thoải mái","Chép rồi chia sẻ cho cả lớp dùng","Đổi tên phần mềm rồi mới dùng"],"a":"Không sao chép trái phép, chỉ dùng khi được phép hoặc nhờ người lớn mua bản quyền","h":"Hãy nhớ bài học về tôn trọng bản quyền.","e":"Sao chép phần mềm có bản quyền khi chưa được phép là vi phạm bản quyền.","t":"tin-cap1","l":"kho"},{"p":"Thư điện tử (email) dùng để làm gì?","o":["Gửi và nhận thư qua Internet","Để vẽ tranh trên máy tính","Để chơi trò chơi","Để nghe nhạc"],"a":"Gửi và nhận thư qua Internet","h":"Email giống như thư tay nhưng được gửi qua mạng.","e":"Email giúp em gửi và nhận thư, kèm tệp đính kèm, qua mạng Internet rất nhanh.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Địa chỉ email luôn có kí tự đặc biệt nào?","o":["Kí tự @","Kí tự #","Kí tự %","Kí tự &"],"a":"Kí tự @","h":"Kí tự này đứng giữa tên người dùng và tên nhà cung cấp dịch vụ thư.","e":"Địa chỉ email gồm tên người dùng, kí tự @ và tên nhà cung cấp dịch vụ.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Trong phần mềm lập trình Scratch, sân khấu là gì?","o":["Khu vực hiển thị nhân vật và kết quả chạy chương trình","Nơi chứa các khối lệnh để kéo thả","Chỗ để viết thư điện tử","Một phần mềm vẽ tranh"],"a":"Khu vực hiển thị nhân vật và kết quả chạy chương trình","h":"Đó là khu vực lớn nơi nhân vật biểu diễn.","e":"Sân khấu là nơi nhân vật xuất hiện và chương trình của em được trình diễn.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Khối lệnh vòng lặp trong Scratch giúp em làm gì?","o":["Lặp lại một việc nhiều lần mà không cần xếp lại nhiều khối lệnh giống nhau","Làm nhân vật biến mất","Đổi màu sân khấu","Tắt máy tính"],"a":"Lặp lại một việc nhiều lần mà không cần xếp lại nhiều khối lệnh giống nhau","h":"Nhờ vòng lặp, chương trình của em ngắn gọn hơn.","e":"Vòng lặp giúp các lệnh bên trong được thực hiện lặp lại nhiều lần.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Để chương trình Scratch bắt đầu chạy khi em nháy chuột vào lá cờ xanh, em dùng nhóm khối lệnh nào?","o":["Khối lệnh sự kiện","Khối lệnh âm thanh","Khối lệnh hiển thị","Khối lệnh bút vẽ"],"a":"Khối lệnh sự kiện","h":"Nhóm khối lệnh này có khối lệnh bắt đầu bằng chữ Khi.","e":"Khối lệnh sự kiện Khi bấm vào lá cờ xanh giúp chương trình bắt đầu chạy.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Em nhận được thư điện tử từ người lạ mời nhận quà và yêu cầu gửi thông tin cá nhân. Em nên làm gì?","o":["Không trả lời, không làm theo và báo cho người lớn","Gửi ngay thông tin cá nhân của mình","Nhờ bạn bè gửi thông tin giúp","Trả lời thư để hỏi thêm về quà"],"a":"Không trả lời, không làm theo và báo cho người lớn","h":"Thư lạ hứa tặng quà thường là bẫy lừa đảo.","e":"Thư lạ có thể là lừa đảo; em không cung cấp thông tin cá nhân và hãy báo cho người lớn.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Muốn bài trình chiếu sinh động hơn khi thuyết trình, em có thể thêm gì vào trang chiếu?","o":["Hiệu ứng cho chữ và hình ảnh","Xoá hết chữ trên trang chiếu","Chỉ để một trang trắng","Tắt loa của máy tính"],"a":"Hiệu ứng cho chữ và hình ảnh","h":"Điều này giúp chữ và hình xuất hiện bắt mắt hơn.","e":"Hiệu ứng giúp chữ và hình ảnh xuất hiện sinh động, thu hút người xem.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Trong soạn thảo văn bản, bảng (table) giúp em làm gì?","o":["Trình bày thông tin theo hàng và cột cho rõ ràng","Để nghe nhạc","Để vẽ hình tròn","Để đổi màu chữ"],"a":"Trình bày thông tin theo hàng và cột cho rõ ràng","h":"Hãy nghĩ đến thời khoá biểu được kẻ thành ô.","e":"Bảng giúp em sắp xếp thông tin thành hàng và cột, dễ đọc và dễ so sánh.","t":"tin-cap1","l":"nhe-nhang"},{"p":"Khi tìm kiếm thông tin trên Internet, cách nào giúp em tìm được kết quả đúng và nhanh hơn?","o":["Dùng từ khoá cụ thể, sát với điều cần tìm","Dùng từ khoá thật chung chung","Gõ sai chính tả thật nhiều","Chỉ gõ một chữ cái duy nhất"],"a":"Dùng từ khoá cụ thể, sát với điều cần tìm","h":"Từ khoá càng rõ ràng, máy tìm kiếm càng hiểu đúng ý em.","e":"Từ khoá cụ thể giúp máy tìm kiếm lọc ra đúng thông tin em cần.","t":"tin-cap1","l":"thu-thach"},{"p":"Em muốn gửi kèm một bức ảnh vào thư điện tử cho bạn. Em cần dùng chức năng nào?","o":["Đính kèm tệp","Xoá thư","Chuyển tiếp thư","In thư ra giấy"],"a":"Đính kèm tệp","h":"Chức năng này thường có biểu tượng chiếc kẹp giấy.","e":"Chức năng đính kèm tệp cho phép em gửi ảnh và tài liệu cùng với thư.","t":"tin-cap1","l":"thu-thach"},{"p":"Trong Scratch, muốn nhân vật di chuyển tiến lên phía trước, em dùng khối lệnh nào?","o":["Khối lệnh di chuyển 10 bước","Khối lệnh nói Xin chào","Khối lệnh phát ra âm thanh","Khối lệnh đổi trang phục"],"a":"Khối lệnh di chuyển 10 bước","h":"Khối lệnh này nằm trong nhóm lệnh Chuyển động.","e":"Khối lệnh di chuyển giúp nhân vật tiến lên phía trước theo số bước em đặt.","t":"tin-cap1","l":"thu-thach"},{"p":"Vì sao em nên đối chiếu thông tin tìm được trên Internet từ nhiều nguồn khác nhau?","o":["Vì không phải thông tin nào trên mạng cũng đúng","Vì xem nhiều trang cho vui","Vì máy tính bắt buộc như vậy","Vì để mất nhiều thời gian hơn"],"a":"Vì không phải thông tin nào trên mạng cũng đúng","h":"Trên mạng có cả thông tin đúng và thông tin sai.","e":"Đối chiếu nhiều nguồn giúp em chọn được thông tin đáng tin cậy.","t":"tin-cap1","l":"thu-thach"},{"p":"Việc nào sau đây giúp em an toàn khi sử dụng mạng Internet?","o":["Không chia sẻ mật khẩu và thông tin cá nhân cho người lạ","Kết bạn rồi hẹn gặp mặt người lạ quen qua mạng","Tải mọi phần mềm lạ về máy","Gửi ảnh cá nhân cho người không quen biết"],"a":"Không chia sẻ mật khẩu và thông tin cá nhân cho người lạ","h":"Hãy giữ kín những thông tin riêng tư của mình.","e":"Giữ kín mật khẩu và thông tin cá nhân giúp em an toàn trên môi trường mạng.","t":"tin-cap1","l":"thu-thach"},{"p":"Em lập trình Scratch cho nhân vật vẽ hình vuông: lặp lại 4 lần hai việc di chuyển 100 bước và quay 90 độ. Cách xếp lệnh nào gọn và đúng nhất?","o":["Dùng khối lệnh lặp lại 4 lần chứa hai lệnh di chuyển và quay","Xếp 8 khối lệnh rời nhau giống hệt nhau","Dùng một khối lệnh chờ","Dùng khối lệnh phát âm thanh"],"a":"Dùng khối lệnh lặp lại 4 lần chứa hai lệnh di chuyển và quay","h":"Việc lặp đi lặp lại nhiều lần nên giao cho vòng lặp.","e":"Dùng vòng lặp 4 lần giúp chương trình ngắn gọn mà vẫn vẽ đúng hình vuông.","t":"tin-cap1","l":"kho"},{"p":"Phần mềm có bản quyền và phần mềm miễn phí khác nhau ở điểm nào?","o":["Phần mềm có bản quyền chỉ được dùng và sao chép khi được tác giả cho phép, còn phần mềm miễn phí được dùng miễn phí theo điều kiện của tác giả","Phần mềm miễn phí luôn tốt hơn phần mềm có bản quyền","Phần mềm có bản quyền thì không cần cài đặt","Cả hai loại đều được sao chép thoải mái"],"a":"Phần mềm có bản quyền chỉ được dùng và sao chép khi được tác giả cho phép, còn phần mềm miễn phí được dùng miễn phí theo điều kiện của tác giả","h":"Điểm khác nhau nằm ở quyền sử dụng và sao chép phần mềm.","e":"Dù miễn phí hay có bản quyền, em đều phải tôn trọng điều kiện sử dụng của tác giả phần mềm.","t":"tin-cap1","l":"kho"},{"p":"Thông tin là gì?","o":["Dữ liệu chưa được xử lí","Những hiểu biết của con người về một sự vật, sự kiện","Một thiết bị lưu trữ dữ liệu","Một chương trình máy tính"],"a":"Những hiểu biết của con người về một sự vật, sự kiện","h":"Thông tin gắn với sự hiểu biết của con người.","e":"Thông tin là những hiểu biết của con người về sự vật, sự kiện, thu nhận qua nghe, nhìn, đọc,...","t":"tin-cap2","l":"nhe-nhang"},{"p":"Đơn vị nhỏ nhất để biểu diễn thông tin trong máy tính là gì?","o":["Byte","Bit","KB","MB"],"a":"Bit","h":"Đơn vị này chỉ nhận một trong hai giá trị 0 hoặc 1.","e":"Bit là đơn vị nhỏ nhất biểu diễn thông tin trong máy tính, chỉ gồm kí hiệu 0 hoặc 1.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Một byte bằng bao nhiêu bit?","o":["2 bit","4 bit","8 bit","16 bit"],"a":"8 bit","h":"Hãy nhớ: 1 byte = 8 bit.","e":"Một byte gồm 8 bit và thường dùng để biểu diễn một kí tự.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Vật nào sau đây là thiết bị lưu trữ dữ liệu?","o":["Màn hình","Bàn phím","Thẻ nhớ USB","Loa"],"a":"Thẻ nhớ USB","h":"Thiết bị lưu trữ giúp giữ lại dữ liệu để dùng sau.","e":"Thẻ nhớ USB là thiết bị lưu trữ; màn hình là thiết bị ra, bàn phím là thiết bị vào, loa là thiết bị ra.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Mạng máy tính là gì?","o":["Một máy tính có cấu hình mạnh","Tập hợp các máy tính được kết nối với nhau để trao đổi thông tin và chia sẻ tài nguyên","Một chương trình diệt virus","Một loại cáp kết nối"],"a":"Tập hợp các máy tính được kết nối với nhau để trao đổi thông tin và chia sẻ tài nguyên","h":"Mạng gồm nhiều máy tính liên kết với nhau.","e":"Mạng máy tính là tập hợp các máy tính được kết nối để trao đổi thông tin và chia sẻ tài nguyên như máy in, dữ liệu.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Mạng LAN là loại mạng nào?","o":["Mạng diện rộng, kết nối các quốc gia","Mạng cục bộ, kết nối các máy tính trong phạm vi hẹp như một trường học hay cơ quan","Mạng không dây toàn cầu","Mạng của một nhà cung cấp dịch vụ Internet"],"a":"Mạng cục bộ, kết nối các máy tính trong phạm vi hẹp như một trường học hay cơ quan","h":"LAN viết tắt của Local Area Network.","e":"LAN là mạng cục bộ, phạm vi kết nối hẹp như trong một phòng, một tòa nhà hay một trường học.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong phần mềm soạn thảo văn bản, để in đậm đoạn chữ đã chọn, ta nhấn tổ hợp phím nào?","o":["Ctrl + I","Ctrl + U","Ctrl + B","Ctrl + S"],"a":"Ctrl + B","h":"B là viết tắt của Bold (đậm).","e":"Ctrl + B dùng để in đậm; Ctrl + I in nghiêng, Ctrl + U gạch chân, Ctrl + S lưu văn bản.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Thuật toán là gì?","o":["Một phần mềm soạn thảo văn bản","Dãy các bước rõ ràng, được sắp xếp theo trình tự để giải quyết một vấn đề","Một thiết bị của máy tính","Một trò chơi trên máy tính"],"a":"Dãy các bước rõ ràng, được sắp xếp theo trình tự để giải quyết một vấn đề","h":"Thuật toán giống như một bản hướng dẫn gồm từng bước.","e":"Thuật toán là dãy hữu hạn các bước rõ ràng, thực hiện theo trình tự để giải quyết một vấn đề.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Một KB (kilobyte) bằng bao nhiêu byte?","o":["100 byte","1000 byte","1024 byte","2048 byte"],"a":"1024 byte","h":"Các đơn vị dung lượng tăng theo bội số 1024.","e":"Theo quy ước trong tin học, 1 KB = 1024 byte, 1 MB = 1024 KB.","t":"tin-cap2","l":"thu-thach"},{"p":"Để chèn một bảng (table) vào văn bản, ta sử dụng lệnh trong thẻ (tab) nào?","o":["Home","Insert","Design","View"],"a":"Insert","h":"Insert nghĩa là 'chèn'.","e":"Lệnh Table nằm trong thẻ Insert, dùng để chèn bảng, hình ảnh, hình vẽ vào văn bản.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong sơ đồ khối mô tả thuật toán, hình thoi được dùng để biểu diễn bước nào?","o":["Bước bắt đầu, kết thúc","Bước nhập hoặc xuất dữ liệu","Bước kiểm tra điều kiện","Bước thực hiện phép tính"],"a":"Bước kiểm tra điều kiện","h":"Hình thoi là nơi thuật toán phải 'quyết định' đi đường nào.","e":"Trong sơ đồ khối, hình thoi biểu diễn bước kiểm tra điều kiện để rẽ nhánh; hình ô van là bắt đầu/kết thúc, hình bình hành là nhập/xuất.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong phần mềm trình chiếu, để bắt đầu trình chiếu từ trang đầu tiên, ta nhấn phím nào?","o":["Esc","F5","Enter","Tab"],"a":"F5","h":"Phím chức năng ở hàng trên cùng của bàn phím.","e":"Nhấn phím F5 để trình chiếu từ đầu; nhấn Esc để thoát khỏi chế độ trình chiếu.","t":"tin-cap2","l":"thu-thach"},{"p":"Điểm khác nhau cơ bản giữa mạng WAN và mạng LAN là gì?","o":["WAN dùng cáp, LAN không dùng cáp","WAN có phạm vi kết nối rộng hơn LAN, có thể giữa các thành phố, quốc gia","LAN nhanh hơn mọi mạng WAN trong mọi trường hợp","WAN chỉ gồm đúng hai máy tính"],"a":"WAN có phạm vi kết nối rộng hơn LAN, có thể giữa các thành phố, quốc gia","h":"So sánh về phạm vi địa lí của hai loại mạng.","e":"LAN là mạng cục bộ phạm vi hẹp; WAN là mạng diện rộng, kết nối các mạng LAN ở khoảng cách xa nhau.","t":"tin-cap2","l":"thu-thach"},{"p":"Một tệp ảnh có dung lượng 2 MB. Dung lượng đó bằng bao nhiêu KB?","o":["2000 KB","1024 KB","2048 KB","4096 KB"],"a":"2048 KB","h":"1 MB = 1024 KB, nhân lên với 2.","e":"1 MB = 1024 KB nên 2 MB = 2 × 1024 = 2048 KB.","t":"tin-cap2","l":"kho"},{"p":"Một thư mục chứa ba tệp có dung lượng lần lượt là 512 KB, 1 MB và 256 KB. Tổng dung lượng của thư mục là bao nhiêu KB?","o":["768 KB","1536 KB","1792 KB","2048 KB"],"a":"1792 KB","h":"Đổi 1 MB ra KB rồi cộng cả ba số lại.","e":"1 MB = 1024 KB, vậy tổng là 512 + 1024 + 256 = 1792 KB.","t":"tin-cap2","l":"kho"},{"p":"Thiết bị nào sau đây là thiết bị VÀO của máy tính?","o":["Màn hình","Bàn phím","Máy in","Loa"],"a":"Bàn phím","h":"Thiết bị vào giúp đưa thông tin vào máy tính.","e":"Bàn phím là thiết bị vào; màn hình, máy in và loa là các thiết bị ra.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Chức năng chính của hệ điều hành là gì?","o":["Soạn thảo văn bản","Quản lí và điều khiển mọi hoạt động của máy tính","Lướt web và xem phim","Diệt mọi loại virus"],"a":"Quản lí và điều khiển mọi hoạt động của máy tính","h":"Hệ điều hành là phần mềm nền tảng chạy đầu tiên khi mở máy.","e":"Hệ điều hành quản lí phần cứng, tổ chức lưu trữ dữ liệu và điều phối các chương trình khác hoạt động.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Windows là tên của phần mềm nào?","o":["Trình duyệt web","Hệ điều hành","Phần mềm bảng tính","Phần mềm diệt virus"],"a":"Hệ điều hành","h":"Đây là phần mềm của hãng Microsoft, rất phổ biến trên máy tính cá nhân.","e":"Windows là hệ điều hành thông dụng do Microsoft phát triển.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Tệp tin (file) là gì?","o":["Một thư mục chứa nhiều chương trình","Một tập hợp dữ liệu được lưu trữ trên bộ nhớ ngoài và được đặt tên","Một thiết bị lưu trữ","Một loại vi rút máy tính"],"a":"Một tập hợp dữ liệu được lưu trữ trên bộ nhớ ngoài và được đặt tên","h":"Mỗi tệp đều có một cái tên riêng.","e":"Tệp tin là tập hợp dữ liệu được lưu trên bộ nhớ ngoài (như ổ cứng, USB) và có tên để quản lí.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong phần mềm bảng tính, ô tính được tạo thành bởi giao nhau của thành phần nào?","o":["Hai hàng","Hai cột","Một cột và một hàng","Một trang tính và một hàng"],"a":"Một cột và một hàng","h":"Hãy hình dung bảng tính như một lưới kẻ ô.","e":"Ô tính là giao của một cột và một hàng trên trang tính.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Địa chỉ ô A5 trong bảng tính có nghĩa là gì?","o":["Ô ở hàng A, cột 5","Ô ở cột A, hàng 5","Ô ở cột 5, hàng A","Ô thứ 5 của trang tính đầu tiên"],"a":"Ô ở cột A, hàng 5","h":"Địa chỉ ô viết theo dạng: chữ cái cột trước, số hàng sau.","e":"Địa chỉ ô gồm tên cột viết trước và số hàng viết sau, nên A5 là ô thuộc cột A, hàng 5.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong phần mềm bảng tính, một công thức luôn bắt đầu bằng kí tự nào?","o":["Dấu +","Dấu =","Dấu #","Dấu @"],"a":"Dấu =","h":"Đây là quy ước bắt buộc để phần mềm hiểu đó là công thức.","e":"Mọi công thức trong bảng tính đều bắt đầu bằng dấu =, sau đó là các toán hạng và phép toán.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Hàm SUM trong phần mềm bảng tính dùng để làm gì?","o":["Tính giá trị trung bình","Tính tổng các số","Tìm số lớn nhất","Đếm số ô có dữ liệu"],"a":"Tính tổng các số","h":"SUM trong tiếng Anh có nghĩa là 'tổng'.","e":"Hàm SUM dùng để tính tổng các giá trị số trong một vùng ô.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Hàm AVERAGE trong phần mềm bảng tính dùng để làm gì?","o":["Tính tổng các số","Tính giá trị trung bình cộng của các số","Tìm số nhỏ nhất","Sắp xếp dữ liệu"],"a":"Tính giá trị trung bình cộng của các số","h":"AVERAGE trong tiếng Anh có nghĩa là 'trung bình'.","e":"Hàm AVERAGE tính trung bình cộng của các giá trị trong vùng ô được chọn.","t":"tin-cap2","l":"thu-thach"},{"p":"Thư mục (folder) trong máy tính được dùng để làm gì?","o":["Tăng tốc độ xử lí của máy tính","Chứa và tổ chức các tệp tin và thư mục con một cách khoa học","Kết nối máy tính với Internet","Bảo vệ máy tính khỏi virus"],"a":"Chứa và tổ chức các tệp tin và thư mục con một cách khoa học","h":"Giống như ngăn tủ dùng để sắp xếp hồ sơ gọn gàng.","e":"Thư mục giúp tổ chức, sắp xếp các tệp và thư mục con theo cấu trúc cây để dễ quản lí và tìm kiếm.","t":"tin-cap2","l":"thu-thach"},{"p":"Hành vi nào sau đây thể hiện ứng xử văn minh trên mạng xã hội?","o":["Chia sẻ ngay mọi tin tức giật gân chưa kiểm chứng","Dùng lời lẽ xúc phạm người khác khi tranh luận","Kiểm chứng thông tin trước khi chia sẻ và tôn trọng người khác","Đăng ảnh của bạn bè mà không cần hỏi ý kiến"],"a":"Kiểm chứng thông tin trước khi chia sẻ và tôn trọng người khác","h":"Hãy nghĩ về trách nhiệm của mình với mỗi bài đăng.","e":"Ứng xử văn minh trên mạng gồm: kiểm chứng thông tin, tôn trọng người khác và không phát tán tin giả.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong thuật toán, bước 'Nếu điểm kiểm tra từ 5 trở lên thì xếp loại Đạt, ngược lại xếp loại Chưa đạt' thuộc cấu trúc nào?","o":["Cấu trúc tuần tự","Cấu trúc rẽ nhánh","Cấu trúc lặp","Cấu trúc lưu trữ"],"a":"Cấu trúc rẽ nhánh","h":"Thuật toán phải chọn một trong hai hướng tùy theo điều kiện.","e":"Khi việc thực hiện bước tiếp theo phụ thuộc vào một điều kiện đúng hay sai, đó là cấu trúc rẽ nhánh.","t":"tin-cap2","l":"thu-thach"},{"p":"Thiết bị nào sau đây vừa là thiết bị vào, vừa là thiết bị ra?","o":["Chuột máy tính","Màn hình cảm ứng","Máy in","Bàn phím"],"a":"Màn hình cảm ứng","h":"Thiết bị này vừa hiển thị thông tin, vừa nhận lệnh chạm của người dùng.","e":"Màn hình cảm ứng vừa hiển thị thông tin (thiết bị ra) vừa nhận thao tác chạm để đưa lệnh vào (thiết bị vào).","t":"tin-cap2","l":"thu-thach"},{"p":"Trong bảng tính, giá trị của công thức =MAX(3, 7, 5) + MIN(3, 7, 5) là bao nhiêu?","o":["8","10","12","15"],"a":"10","h":"Tìm số lớn nhất và số nhỏ nhất trong ba số rồi cộng lại.","e":"MAX(3, 7, 5) = 7 và MIN(3, 7, 5) = 3, nên kết quả là 7 + 3 = 10.","t":"tin-cap2","l":"kho"},{"p":"Mật khẩu nào sau đây là mật khẩu mạnh nhất?","o":["12345678","matkhau123","Mk@2024#xY","ngaysinh2010"],"a":"Mk@2024#xY","h":"Mật khẩu mạnh cần dài và trộn nhiều loại kí tự khác nhau.","e":"Mật khẩu mạnh gồm chữ hoa, chữ thường, chữ số và kí tự đặc biệt, không chứa thông tin dễ đoán như ngày sinh.","t":"tin-cap2","l":"kho"},{"p":"Quá trình xử lí thông tin bằng máy tính gồm các giai đoạn chính nào?","o":["Thu thập – In ấn – Lưu trữ","Nhận thông tin – Xử lí – Đưa ra kết quả","Soạn thảo – Trình chiếu – Chia sẻ","Tải xuống – Cài đặt – Gỡ bỏ"],"a":"Nhận thông tin – Xử lí – Đưa ra kết quả","h":"Máy tính cũng giống bộ não: tiếp nhận, suy nghĩ rồi trả lời.","e":"Máy tính xử lí thông tin qua ba giai đoạn: nhận thông tin vào, xử lí và đưa kết quả ra.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Hàm IF trong phần mềm bảng tính dùng để làm gì?","o":["Tính tổng một vùng dữ liệu","Kiểm tra một điều kiện và trả về giá trị tương ứng với điều kiện đúng hoặc sai","Vẽ biểu đồ cho dữ liệu","Định dạng màu cho ô tính"],"a":"Kiểm tra một điều kiện và trả về giá trị tương ứng với điều kiện đúng hoặc sai","h":"IF trong tiếng Anh có nghĩa là 'nếu'.","e":"Hàm IF kiểm tra điều kiện: nếu điều kiện đúng thì trả về một giá trị, nếu sai thì trả về giá trị khác.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong lập trình Scratch, biến (variable) được dùng để làm gì?","o":["Trang trí cho nhân vật","Lưu trữ giá trị có thể thay đổi trong khi chương trình chạy","Phát nhạc nền","Kết nối máy tính với Internet"],"a":"Lưu trữ giá trị có thể thay đổi trong khi chương trình chạy","h":"Ví dụ: biến 'điểm' tăng dần khi trả lời đúng trong một trò chơi.","e":"Biến là nơi lưu trữ giá trị, và giá trị đó có thể thay đổi trong quá trình chương trình hoạt động.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Biểu đồ cột thường được dùng với mục đích chính nào?","o":["Thể hiện tỉ lệ phần trăm của một tổng thể","So sánh dữ liệu giữa các đối tượng","Thể hiện sự thay đổi theo thời gian liên tục","Trang trí cho trang tính"],"a":"So sánh dữ liệu giữa các đối tượng","h":"Chiều cao của các cột giúp ta nhìn ra ngay đối tượng nào hơn kém nhau.","e":"Biểu đồ cột dùng để so sánh số liệu giữa các đối tượng; biểu đồ quạt tròn dùng để thể hiện tỉ lệ phần trăm.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Hành vi nào sau đây vi phạm bản quyền trong môi trường số?","o":["Mua phần mềm có bản quyền để sử dụng","Sao chép phần mềm có bản quyền rồi chia sẻ trái phép cho nhiều người","Trích dẫn một đoạn ngắn và ghi rõ nguồn","Sử dụng phần mềm miễn phí theo đúng giấy phép"],"a":"Sao chép phần mềm có bản quyền rồi chia sẻ trái phép cho nhiều người","h":"Hãy tôn trọng công sức và quyền của tác giả sản phẩm số.","e":"Sao chép, phát tán sản phẩm số có bản quyền khi chưa được phép là hành vi vi phạm bản quyền.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Chức năng sắp xếp (Sort) dữ liệu trong bảng tính có tác dụng gì?","o":["Xoá bớt các hàng không cần thiết","Sắp xếp các hàng theo thứ tự tăng dần hoặc giảm dần của một cột dữ liệu","Đổi màu nền của bảng dữ liệu","Tạo biểu đồ từ dữ liệu"],"a":"Sắp xếp các hàng theo thứ tự tăng dần hoặc giảm dần của một cột dữ liệu","h":"Ví dụ: xếp danh sách học sinh theo điểm từ cao xuống thấp.","e":"Sắp xếp dữ liệu là bố trí lại các hàng theo thứ tự tăng dần hoặc giảm dần dựa trên giá trị của một cột.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Chức năng lọc (Filter) dữ liệu trong bảng tính dùng để làm gì?","o":["Tính tổng toàn bộ dữ liệu","Chỉ hiển thị các hàng thoả mãn điều kiện đặt ra, tạm ẩn các hàng còn lại","Sao chép dữ liệu sang trang tính khác","In dữ liệu ra giấy"],"a":"Chỉ hiển thị các hàng thoả mãn điều kiện đặt ra, tạm ẩn các hàng còn lại","h":"Ví dụ: chỉ xem những học sinh có điểm Toán từ 8 trở lên.","e":"Lọc dữ liệu giúp chỉ hiển thị các hàng thoả mãn điều kiện, các hàng không thoả mãn sẽ tạm thời bị ẩn đi.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Hành vi nào sau đây thể hiện đạo đức tốt khi tham gia môi trường số?","o":["Đăng ảnh của người khác khi chưa được đồng ý","Tôn trọng quyền riêng tư của người khác và không phát tán thông tin cá nhân của họ","Dùng tài khoản giả để nói xấu bạn bè","Tải lậu phim và phần mềm để tiết kiệm tiền"],"a":"Tôn trọng quyền riêng tư của người khác và không phát tán thông tin cá nhân của họ","h":"Hãy đối xử với người khác trên mạng như ngoài đời thực.","e":"Tôn trọng quyền riêng tư, không tự ý đăng tải thông tin hay hình ảnh của người khác là biểu hiện của đạo đức số.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Ô B2 chứa công thức =IF(A2>=5, \"Đạt\", \"Chưa đạt\"). Nếu ô A2 có giá trị 7 thì ô B2 hiển thị kết quả gì?","o":["Chưa đạt","Đạt","7","Báo lỗi công thức"],"a":"Đạt","h":"Kiểm tra xem điều kiện A2>=5 đúng hay sai khi A2 bằng 7.","e":"Vì 7 >= 5 là điều kiện đúng nên hàm IF trả về giá trị 'Đạt'.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong Scratch, khối lệnh 'lặp lại 10 lần' (repeat 10) thuộc cấu trúc điều khiển nào?","o":["Cấu trúc tuần tự","Cấu trúc rẽ nhánh","Cấu trúc lặp","Cấu trúc gán"],"a":"Cấu trúc lặp","h":"Khối lệnh này thực hiện một nhóm lệnh nhiều lần.","e":"Khối 'lặp lại' cho phép thực hiện lặp đi lặp lại một nhóm lệnh, thuộc cấu trúc lặp.","t":"tin-cap2","l":"thu-thach"},{"p":"Trực quan hoá dữ liệu là gì?","o":["Nhập dữ liệu vào máy tính bằng bàn phím","Biểu diễn dữ liệu dưới dạng hình ảnh, biểu đồ để dễ quan sát, so sánh và hiểu","Xoá những dữ liệu không cần thiết","Sao lưu dữ liệu lên đám mây"],"a":"Biểu diễn dữ liệu dưới dạng hình ảnh, biểu đồ để dễ quan sát, so sánh và hiểu","h":"Một biểu đồ thường dễ hiểu hơn một bảng số dài.","e":"Trực quan hoá dữ liệu là dùng hình ảnh, biểu đồ để biểu diễn dữ liệu, giúp con người nắm bắt thông tin nhanh và rõ hơn.","t":"tin-cap2","l":"thu-thach"},{"p":"Khi sử dụng một bức ảnh tìm được trên Internet cho bài đăng của mình, việc làm nào là đúng?","o":["Cứ dùng thoải mái vì ảnh đã công khai trên mạng","Ghi rõ nguồn và tôn trọng bản quyền của tác giả","Xoá tên tác giả đi để tránh rắc rối","Bán lại bức ảnh đó cho người khác"],"a":"Ghi rõ nguồn và tôn trọng bản quyền của tác giả","h":"Ảnh trên mạng vẫn thuộc về tác giả của nó.","e":"Khi dùng tác phẩm của người khác cần tôn trọng bản quyền, ghi nguồn rõ ràng hoặc xin phép khi cần thiết.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong lập trình, biểu thức là gì?","o":["Một câu lệnh in kết quả ra màn hình","Tổ hợp các giá trị, biến và phép toán tạo ra một giá trị","Một loại nhân vật trong Scratch","Tên của một chương trình máy tính"],"a":"Tổ hợp các giá trị, biến và phép toán tạo ra một giá trị","h":"Ví dụ: (a + b) × 2 là một biểu thức.","e":"Biểu thức là sự kết hợp của các toán hạng (giá trị, biến) bằng các phép toán và cho ra một giá trị.","t":"tin-cap2","l":"thu-thach"},{"p":"Để đếm số học sinh có điểm từ 8 trở lên trong vùng điểm D2:D31 của bảng tính, ta nên dùng hàm nào?","o":["SUM","COUNTIF","AVERAGE","MAX"],"a":"COUNTIF","h":"Cần một hàm vừa đếm, vừa xét điều kiện 'từ 8 trở lên'.","e":"Hàm COUNTIF đếm số ô thoả mãn một điều kiện cho trước, ví dụ COUNTIF(D2:D31,\">=8\").","t":"tin-cap2","l":"kho"},{"p":"Trong Scratch, để nhân vật di chuyển liên tục cho đến khi chạm vào cạnh sân khấu mới dừng, ta nên dùng cấu trúc nào?","o":["Một lệnh di chuyển duy nhất","Vòng lặp cho đến khi điều kiện đúng (repeat until)","Câu lệnh rẽ nhánh một lần","Lệnh chờ (wait)"],"a":"Vòng lặp cho đến khi điều kiện đúng (repeat until)","h":"Việc di chuyển phải được kiểm tra điều kiện sau mỗi bước đi.","e":"Cấu trúc 'lặp cho đến khi' (repeat until) giúp lặp lại hành động và dừng lại khi điều kiện chạm cạnh được thoả mãn.","t":"tin-cap2","l":"kho"},{"p":"Trong ngôn ngữ lập trình Python, lệnh print() dùng để làm gì?","o":["Nhập dữ liệu từ bàn phím","Hiển thị thông tin ra màn hình","Lưu chương trình vào tệp","Dừng chương trình ngay lập tức"],"a":"Hiển thị thông tin ra màn hình","h":"print trong tiếng Anh có nghĩa là 'in ra'.","e":"Lệnh print() dùng để đưa thông tin, kết quả ra màn hình.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong Python, lệnh input() dùng để làm gì?","o":["In kết quả ra màn hình","Nhận dữ liệu do người dùng nhập vào từ bàn phím","Tạo một biến mới có giá trị bằng 0","Vẽ hình trên màn hình"],"a":"Nhận dữ liệu do người dùng nhập vào từ bàn phím","h":"input trong tiếng Anh có nghĩa là 'đầu vào'.","e":"Lệnh input() tạm dừng để người dùng nhập dữ liệu từ bàn phím và đưa vào chương trình.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong lập trình, biến được dùng để làm gì?","o":["Lưu trữ giá trị để chương trình sử dụng và thay đổi khi cần","Trang trí giao diện chương trình","Kết nối chương trình với Internet","Bảo vệ chương trình khỏi virus"],"a":"Lưu trữ giá trị để chương trình sử dụng và thay đổi khi cần","h":"Biến giống một chiếc hộp có nhãn, chứa một giá trị.","e":"Biến là vùng nhớ được đặt tên, dùng để lưu giá trị phục vụ quá trình xử lí của chương trình.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Mật khẩu mạnh nên có đặc điểm nào sau đây?","o":["Chỉ gồm ngày tháng năm sinh của mình","Dài, gồm chữ hoa, chữ thường, chữ số và kí tự đặc biệt","Giống với tên tài khoản đăng nhập","Càng ngắn càng dễ nhớ"],"a":"Dài, gồm chữ hoa, chữ thường, chữ số và kí tự đặc biệt","h":"Trộn nhiều loại kí tự khiến mật khẩu khó bị đoán hơn.","e":"Mật khẩu mạnh cần đủ dài, kết hợp chữ hoa, chữ thường, số và kí tự đặc biệt, tránh dùng thông tin cá nhân.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Cơ sở dữ liệu là gì?","o":["Một phần mềm soạn thảo văn bản","Tập hợp dữ liệu được tổ chức, lưu trữ có hệ thống để tiện quản lí và khai thác","Một thiết bị phần cứng của máy tính","Một loại mạng máy tính"],"a":"Tập hợp dữ liệu được tổ chức, lưu trữ có hệ thống để tiện quản lí và khai thác","h":"Ví dụ: dữ liệu học sinh của một trường được tổ chức thành các bảng.","e":"Cơ sở dữ liệu là tập hợp dữ liệu có liên quan, được tổ chức và lưu trữ một cách hệ thống phục vụ quản lí, tra cứu.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong một bảng dữ liệu (ví dụ bảng danh sách học sinh), mỗi hàng của bảng thường biểu diễn điều gì?","o":["Một trường dữ liệu","Một bản ghi về một đối tượng cụ thể","Toàn bộ cơ sở dữ liệu","Một cột dữ liệu"],"a":"Một bản ghi về một đối tượng cụ thể","h":"Mỗi hàng ứng với thông tin của đúng một học sinh.","e":"Trong bảng dữ liệu, mỗi hàng là một bản ghi (record) chứa thông tin về một đối tượng, mỗi cột là một trường dữ liệu.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Phần mềm mô phỏng được sử dụng chủ yếu để làm gì?","o":["Soạn thảo văn bản nhanh hơn","Mô hình hoá một hiện tượng hay quá trình để quan sát và thử nghiệm một cách an toàn","Diệt virus cho máy tính","Nén dữ liệu để tiết kiệm bộ nhớ"],"a":"Mô hình hoá một hiện tượng hay quá trình để quan sát và thử nghiệm một cách an toàn","h":"Ví dụ: mô phỏng lái máy bay giúp phi công tập luyện mà không gặp nguy hiểm thật.","e":"Phần mềm mô phỏng tái hiện hiện tượng, quá trình trên máy tính, giúp học tập và thử nghiệm an toàn, tiết kiệm.","t":"tin-cap2","l":"nhe-nhang"},{"p":"Công việc nào sau đây thuộc lĩnh vực nghề nghiệp tin học?","o":["Lập trình viên phát triển phần mềm","Thợ sửa chữa ô tô","Đầu bếp nhà hàng","Kiến trúc sư xây dựng"],"a":"Lập trình viên phát triển phần mềm","h":"Hãy chọn nghề trực tiếp làm việc với phần mềm và máy tính.","e":"Lập trình viên là nghề tiêu biểu trong lĩnh vực tin học, cùng với các nghề như quản trị mạng, phân tích dữ liệu,...","t":"tin-cap2","l":"nhe-nhang"},{"p":"Trong Python, giá trị \"Xin chào\" thuộc kiểu dữ liệu nào?","o":["Số nguyên","Số thực","Chuỗi kí tự","Danh sách"],"a":"Chuỗi kí tự","h":"Giá trị này được đặt trong dấu ngoặc kép.","e":"Giá trị văn bản đặt trong dấu ngoặc đơn hoặc ngoặc kép thuộc kiểu chuỗi kí tự (str).","t":"tin-cap2","l":"thu-thach"},{"p":"Trong Python, phép toán 7 // 2 cho kết quả bằng bao nhiêu?","o":["3.5","3","2","1"],"a":"3","h":"Dấu // là phép chia lấy phần nguyên.","e":"Phép toán // chia lấy phần nguyên, 7 chia 2 được 3 dư 1 nên kết quả là 3.","t":"tin-cap2","l":"thu-thach"},{"p":"Dấu hiệu nào sau đây cho thấy một tin nhắn 'trúng thưởng' rất có thể là lừa đảo?","o":["Tin nhắn gửi từ số điện thoại của người thân","Yêu cầu bạn gửi mã OTP hoặc nộp một khoản tiền để được nhận quà","Tin nhắn chỉ thông báo mà không yêu cầu gì thêm","Tên đơn vị gửi tin được viết đúng chính tả"],"a":"Yêu cầu bạn gửi mã OTP hoặc nộp một khoản tiền để được nhận quà","h":"Không một giải thưởng thật nào bắt bạn nộp tiền hay lộ mã OTP.","e":"Kẻ lừa đảo thường yêu cầu nộp 'phí nhận thưởng' hoặc cung cấp mã OTP, mật khẩu — đây là dấu hiệu lừa đảo điển hình.","t":"tin-cap2","l":"thu-thach"},{"p":"Trong bảng dữ liệu học sinh, các cột 'Họ và tên', 'Ngày sinh', 'Lớp' được gọi là gì?","o":["Các bản ghi","Các trường dữ liệu","Các bảng phụ","Các khoá chính"],"a":"Các trường dữ liệu","h":"Mỗi cột mô tả một thuộc tính của đối tượng.","e":"Mỗi cột trong bảng dữ liệu là một trường (field) mô tả một thuộc tính, ví dụ họ tên, ngày sinh, lớp.","t":"tin-cap2","l":"thu-thach"},{"p":"Vòng lặp for trong lập trình thường được sử dụng hiệu quả nhất trong trường hợp nào?","o":["Khi không thể biết chương trình sẽ chạy bao lâu","Khi biết trước số lần cần lặp lại công việc","Khi chỉ cần kiểm tra một điều kiện duy nhất","Khi muốn chương trình dừng ngay lập tức"],"a":"Khi biết trước số lần cần lặp lại công việc","h":"Ví dụ: in bảng cửu chương 5 đúng 10 dòng.","e":"Vòng lặp for phù hợp khi số lần lặp đã biết trước; vòng lặp while phù hợp khi lặp theo điều kiện.","t":"tin-cap2","l":"thu-thach"},{"p":"Cho đoạn chương trình Python: x = 5; x = x + 3; print(x). Chương trình in ra kết quả nào?","o":["5","3","8","x + 3"],"a":"8","h":"Hãy theo dõi giá trị của biến x qua từng lệnh.","e":"Ban đầu x = 5, lệnh x = x + 3 gán lại x = 5 + 3 = 8, nên print(x) in ra 8.","t":"tin-cap2","l":"kho"},{"p":"Ngoài việc đặt mật khẩu mạnh, biện pháp nào sau đây giúp bảo vệ tài khoản trực tuyến tốt nhất?","o":["Đăng nhập tài khoản trên càng nhiều máy càng tốt","Bật xác thực hai yếu tố cho tài khoản","Chia sẻ mật khẩu với bạn thân để nhờ giữ hộ","Tắt mọi thông báo đăng nhập lạ"],"a":"Bật xác thực hai yếu tố cho tài khoản","h":"Thêm một lớp bảo vệ ngoài mật khẩu, ví dụ mã gửi về điện thoại.","e":"Xác thực hai yếu tố thêm một lớp kiểm chứng ngoài mật khẩu, giúp tài khoản an toàn hơn nhiều kể cả khi lộ mật khẩu.","t":"tin-cap2","l":"kho"},{"p":"Trí tuệ nhân tạo (AI) là lĩnh vực khoa học máy tính nhằm giúp máy tính thực hiện được những công việc nào?","o":["Những công việc vốn cần đến trí thông minh của con người","Chỉ những công việc tính toán đơn giản","Việc in ấn tài liệu","Việc lưu trữ tệp tin"],"a":"Những công việc vốn cần đến trí thông minh của con người","h":"Nghĩ tới các việc như nhận diện giọng nói, hình ảnh, trò chuyện.","e":"AI hướng tới giúp máy thực hiện các công việc cần trí thông minh như con người: học, suy luận, nhận dạng.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Ví dụ nào sau đây là ứng dụng của Internet vạn vật (IoT) trong đời sống?","o":["Đèn trong nhà được bật, tắt từ xa qua điện thoại","Máy tính để bàn dùng để soạn văn bản","Máy in phun mực in tài liệu","Ổ cứng di động để chép dữ liệu"],"a":"Đèn trong nhà được bật, tắt từ xa qua điện thoại","h":"IoT là các đồ vật kết nối Internet và điều khiển được từ xa.","e":"Đèn thông minh kết nối Internet, nhận lệnh từ điện thoại là một ứng dụng điển hình của IoT.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Dữ liệu lớn (Big Data) thường được nhắc đến với những đặc điểm nào?","o":["Khối lượng rất lớn, tốc độ tạo ra nhanh và dạng dữ liệu đa dạng","Chỉ gồm các con số trong một bảng tính","Luôn được lưu trên một máy tính duy nhất","Không cần qua xử lí vẫn dùng được ngay"],"a":"Khối lượng rất lớn, tốc độ tạo ra nhanh và dạng dữ liệu đa dạng","h":"Nhớ ba chữ V thường được nhắc tới: khối lượng, tốc độ, đa dạng.","e":"Dữ liệu lớn có khối lượng khổng lồ, sinh ra nhanh và đa dạng về dạng (văn bản, hình ảnh, video...).","t":"tin-cap3","l":"nhe-nhang"},{"p":"Mạng cục bộ (LAN) là mạng máy tính có phạm vi kết nối như thế nào?","o":["Trong một khu vực nhỏ như phòng học, văn phòng, cơ quan","Trên phạm vi toàn quốc","Trên phạm vi toàn thế giới","Giữa các châu lục với nhau"],"a":"Trong một khu vực nhỏ như phòng học, văn phòng, cơ quan","h":"Chữ L trong LAN là Local — cục bộ, phạm vi hẹp.","e":"LAN kết nối các máy tính trong phạm vi hẹp như một phòng, một toà nhà hay một cơ quan.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Địa chỉ IP trong mạng máy tính dùng để làm gì?","o":["Định danh một thiết bị khi tham gia vào mạng","Tăng tốc độ xử lí của máy tính","Lưu trữ dữ liệu cho người dùng","Dịch nội dung trang web sang tiếng Việt"],"a":"Định danh một thiết bị khi tham gia vào mạng","h":"Giống như số nhà để thư được gửi đến đúng nơi.","e":"Mỗi thiết bị tham gia mạng có một địa chỉ IP để các thiết bị khác nhận diện và gửi dữ liệu tới.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Hệ điều hành là phần mềm có vai trò gì?","o":["Quản lí, điều khiển phần cứng và làm nền cho các phần mềm khác hoạt động","Dùng để chơi trò chơi điện tử","Dùng để soạn thảo văn bản","Dùng để lướt web và xem video"],"a":"Quản lí, điều khiển phần cứng và làm nền cho các phần mềm khác hoạt động","h":"Windows, Android, iOS đều là các hệ điều hành quen thuộc.","e":"Hệ điều hành quản lí phần cứng, điều phối tài nguyên và tạo môi trường cho các phần mềm ứng dụng chạy.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Trong ngôn ngữ lập trình Python, để hiển thị kết quả ra màn hình ta dùng lệnh nào?","o":["print()","write()","show()","display()"],"a":"print()","h":"Lệnh này trong tiếng Anh có nghĩa là 'in ra'.","e":"Python dùng hàm print() để đưa dữ liệu ra màn hình.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Hành vi nào sau đây vi phạm bản quyền phần mềm?","o":["Sao chép, chia sẻ phần mềm có bản quyền khi chưa được chủ sở hữu cho phép","Mua phần mềm bản quyền để sử dụng","Dùng phần mềm mã nguồn mở theo đúng giấy phép của nó","Tự viết một phần mềm của riêng mình"],"a":"Sao chép, chia sẻ phần mềm có bản quyền khi chưa được chủ sở hữu cho phép","h":"Bản quyền là quyền của tác giả/chủ sở hữu đối với sản phẩm của họ.","e":"Sao chép và phát tán phần mềm có bản quyền trái phép là hành vi xâm phạm bản quyền.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Hệ thống tên miền DNS có nhiệm vụ chính là gì?","o":["Chuyển đổi tên miền thành địa chỉ IP tương ứng","Bảo vệ máy tính khỏi virus","Nén dữ liệu để truyền nhanh hơn","Tăng dung lượng cho ổ cứng"],"a":"Chuyển đổi tên miền thành địa chỉ IP tương ứng","h":"Nhờ DNS ta chỉ cần nhớ tên như google.com thay vì dãy số IP.","e":"DNS phân giải tên miền (dễ nhớ với con người) thành địa chỉ IP để máy tính kết nối đúng máy chủ.","t":"tin-cap3","l":"thu-thach"},{"p":"Cho đoạn chương trình Python: x = 5; x = x + 3; print(x). Màn hình sẽ hiển thị số nào?","o":["8","5","3","53"],"a":"8","h":"Giá trị của x được cập nhật: lấy x cũ cộng thêm 3.","e":"x ban đầu bằng 5, sau lệnh gán x = x + 3 thì x bằng 8 và được in ra.","t":"tin-cap3","l":"thu-thach"},{"p":"Giao thức trong mạng máy tính được hiểu là gì?","o":["Tập hợp các quy tắc mà các thiết bị tuân theo để trao đổi dữ liệu với nhau","Một loại cáp dùng để nối mạng","Tên gọi của một hãng sản xuất máy tính","Một phần mềm soạn thảo văn bản"],"a":"Tập hợp các quy tắc mà các thiết bị tuân theo để trao đổi dữ liệu với nhau","h":"Giống như hai người muốn nói chuyện thì phải chung một 'luật' giao tiếp.","e":"Giao thức là tập hợp quy tắc, quy ước về định dạng và cách truyền dữ liệu giữa các thiết bị trong mạng.","t":"tin-cap3","l":"thu-thach"},{"p":"Phát biểu nào sau đây đúng về Internet vạn vật (IoT)?","o":["Các đồ vật được gắn cảm biến, kết nối Internet để thu thập và trao đổi dữ liệu","IoT chỉ áp dụng cho máy tính để bàn","IoT hoạt động mà không cần kết nối mạng","IoT là tên một trò chơi trực tuyến nhiều người chơi"],"a":"Các đồ vật được gắn cảm biến, kết nối Internet để thu thập và trao đổi dữ liệu","h":"Hãy nghĩ tới đồng hồ thông minh, camera, nhà thông minh.","e":"IoT kết nối các đồ vật có cảm biến qua Internet để chúng thu thập, trao đổi dữ liệu và phục vụ con người.","t":"tin-cap3","l":"thu-thach"},{"p":"Trong Python, câu lệnh rẽ nhánh (điều kiện) bắt đầu bằng từ khoá nào?","o":["if","when","check","case"],"a":"if","h":"Từ khoá này trong tiếng Anh có nghĩa là 'nếu'.","e":"Python dùng từ khoá if để bắt đầu câu lệnh điều kiện, kèm theo else/elif khi cần.","t":"tin-cap3","l":"thu-thach"},{"p":"Cho đoạn chương trình Python: s = 0; for i in range(1, 5): s = s + i; print(s). Kết quả in ra là bao nhiêu?","o":["10","6","15","4"],"a":"10","h":"Vòng lặp cho i chạy qua các số 1, 2, 3, 4 và cộng dồn vào s.","e":"s = 1 + 2 + 3 + 4 = 10 (range(1, 5) cho các giá trị 1 đến 4).","t":"tin-cap3","l":"kho"},{"p":"Khi một trang web sử dụng giao thức HTTPS thay vì HTTP, điểm khác biệt chính là gì?","o":["Dữ liệu truyền đi được mã hoá nên an toàn hơn","Trang web luôn tải nhanh hơn trong mọi trường hợp","Người dùng không cần mật khẩu khi đăng nhập","Trang web được truy cập hoàn toàn miễn phí"],"a":"Dữ liệu truyền đi được mã hoá nên an toàn hơn","h":"Chữ S trong HTTPS là Secure — an toàn.","e":"HTTPS bổ sung khả năng mã hoá đường truyền, giúp dữ liệu trao đổi giữa người dùng và máy chủ an toàn hơn HTTP.","t":"tin-cap3","l":"kho"},{"p":"Cơ sở dữ liệu (CSDL) là gì?","o":["Tập hợp dữ liệu có liên quan với nhau, được tổ chức và lưu trữ để phục vụ khai thác, quản lí","Một phần mềm dùng để soạn thảo văn bản","Một thiết bị dùng để lưu trữ dữ liệu","Một ngôn ngữ lập trình phổ biến"],"a":"Tập hợp dữ liệu có liên quan với nhau, được tổ chức và lưu trữ để phục vụ khai thác, quản lí","h":"Ví dụ: dữ liệu học sinh của một trường được tổ chức thành các bảng liên quan.","e":"CSDL là tập hợp dữ liệu có liên quan, được tổ chức theo cấu trúc nhất định để lưu trữ và khai thác hiệu quả.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Trong một bảng dữ liệu của CSDL, mỗi hàng (dòng) của bảng được gọi là gì?","o":["Bản ghi","Trường","Khoá chính","Tệp dữ liệu"],"a":"Bản ghi","h":"Mỗi hàng chứa thông tin về một đối tượng cụ thể, ví dụ một học sinh.","e":"Mỗi hàng trong bảng là một bản ghi, lưu thông tin đầy đủ về một đối tượng.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Khoá chính của một bảng dữ liệu có vai trò gì?","o":["Giúp phân biệt các bản ghi với nhau, mỗi bản ghi có giá trị khoá chính riêng","Giúp sắp xếp các bản ghi theo thứ tự bảng chữ cái","Giúp tô màu cho bảng dữ liệu đẹp hơn","Giúp xoá bỏ các dữ liệu không cần thiết"],"a":"Giúp phân biệt các bản ghi với nhau, mỗi bản ghi có giá trị khoá chính riêng","h":"Ví dụ: mã học sinh — mỗi học sinh có một mã duy nhất.","e":"Khoá chính gồm một hoặc một số trường mà giá trị của chúng xác định duy nhất mỗi bản ghi trong bảng.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Microsoft Access là phần mềm thuộc loại nào?","o":["Hệ quản trị cơ sở dữ liệu","Trình duyệt web","Phần mềm chỉnh sửa ảnh","Hệ điều hành"],"a":"Hệ quản trị cơ sở dữ liệu","h":"Đây là phần mềm của Microsoft dùng để tạo và quản lí các bảng dữ liệu.","e":"Access là hệ quản trị CSDL phổ biến, cho phép tạo bảng, truy vấn, biểu mẫu và báo cáo.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Trong Python, một danh sách (list) được viết trong cặp dấu nào?","o":["Dấu ngoặc vuông [ ]","Dấu ngoặc tròn ( )","Dấu ngoặc nhọn { }","Dấu nháy kép \" \""],"a":"Dấu ngoặc vuông [ ]","h":"Ví dụ: diem = [8, 9, 10].","e":"Danh sách trong Python được khai báo bằng cặp dấu ngoặc vuông, các phần tử cách nhau bởi dấu phẩy.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Để định nghĩa một hàm trong Python, ta dùng từ khoá nào?","o":["def","func","function","proc"],"a":"def","h":"Từ khoá này viết tắt của 'define' — định nghĩa.","e":"Python dùng từ khoá def để khai báo hàm, theo sau là tên hàm và các tham số.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Việc đặt mật khẩu mạnh và thường xuyên cập nhật phần mềm đem lại lợi ích gì?","o":["Giúp tăng tính an toàn, bảo mật cho dữ liệu và tài khoản","Giúp máy tính chạy nhanh gấp đôi","Giúp màn hình hiển thị sáng hơn","Giúp tăng dung lượng ổ cứng miễn phí"],"a":"Giúp tăng tính an toàn, bảo mật cho dữ liệu và tài khoản","h":"Mật khẩu dễ đoán và phần mềm lỗi thời là cửa ngõ cho kẻ xấu.","e":"Mật khẩu mạnh khó bị dò đoán; cập nhật phần mềm giúp vá các lỗ hổng bảo mật đã biết.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Công việc nào sau đây thuộc lĩnh vực tin học?","o":["Lập trình viên phát triển phần mềm","Kĩ sư xây dựng cầu đường","Bác sĩ khám chữa bệnh","Đầu bếp nhà hàng"],"a":"Lập trình viên phát triển phần mềm","h":"Hãy chọn công việc gắn trực tiếp với máy tính và phần mềm.","e":"Lập trình viên là nghề tiêu biểu trong lĩnh vực công nghệ thông tin/tin học.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Trong ngôn ngữ truy vấn SQL, câu lệnh SELECT dùng để làm gì?","o":["Truy xuất (lấy) dữ liệu từ các bảng trong CSDL","Xoá hẳn một bảng dữ liệu","Tạo tài khoản người dùng mới","Sao lưu toàn bộ CSDL ra ổ cứng"],"a":"Truy xuất (lấy) dữ liệu từ các bảng trong CSDL","h":"SELECT trong tiếng Anh có nghĩa là 'chọn/lấy ra'.","e":"SELECT là câu lệnh dùng để chọn và lấy ra những dữ liệu cần thiết từ một hay nhiều bảng.","t":"tin-cap3","l":"thu-thach"},{"p":"Trong bảng dữ liệu, 'trường' (field) được hiểu là gì?","o":["Một cột của bảng, thể hiện một thuộc tính của đối tượng","Một hàng của bảng dữ liệu","Toàn bộ bảng dữ liệu","Một tệp tin chứa dữ liệu"],"a":"Một cột của bảng, thể hiện một thuộc tính của đối tượng","h":"Ví dụ bảng Học sinh có các cột: Họ tên, Ngày sinh, Lớp...","e":"Mỗi cột của bảng là một trường, lưu một thuộc tính chung của tất cả các đối tượng trong bảng.","t":"tin-cap3","l":"thu-thach"},{"p":"Trong Python, biểu thức len(\"Tin hoc\") cho kết quả bằng bao nhiêu?","o":["7","6","8","5"],"a":"7","h":"Hãy đếm từng kí tự trong chuỗi, kể cả dấu cách.","e":"Chuỗi \"Tin hoc\" gồm 7 kí tự: T, i, n, dấu cách, h, o, c.","t":"tin-cap3","l":"thu-thach"},{"p":"Thao tác 'lọc dữ liệu' trong CSDL có nghĩa là gì?","o":["Chọn ra những bản ghi thoả mãn một điều kiện nào đó","Xoá toàn bộ dữ liệu của bảng","In toàn bộ bảng ra giấy","Đổi tên cho bảng dữ liệu"],"a":"Chọn ra những bản ghi thoả mãn một điều kiện nào đó","h":"Ví dụ: chỉ hiện những học sinh có điểm trung bình từ 8 trở lên.","e":"Lọc dữ liệu là hiển thị/chọn ra các bản ghi đáp ứng điều kiện đặt ra, ví dụ điểm ≥ 8.","t":"tin-cap3","l":"thu-thach"},{"p":"Hệ quản trị cơ sở dữ liệu (HQTCSDL) là phần mềm dùng để làm gì?","o":["Tạo lập, lưu trữ, cập nhật và khai thác CSDL","Soạn thảo văn bản và trình chiếu","Nghe nhạc và xem phim","Lướt web và gửi thư điện tử"],"a":"Tạo lập, lưu trữ, cập nhật và khai thác CSDL","h":"Access, MySQL, SQL Server là những ví dụ của loại phần mềm này.","e":"HQTCSDL là phần mềm giúp người dùng tạo lập CSDL, thêm/sửa/xoá dữ liệu và truy vấn khai thác thông tin.","t":"tin-cap3","l":"thu-thach"},{"p":"Cho đoạn chương trình Python: a = [2, 4, 6]; a.append(8); print(len(a)). Kết quả in ra là bao nhiêu?","o":["4","3","5","8"],"a":"4","h":"append() thêm một phần tử vào cuối danh sách.","e":"Danh sách ban đầu có 3 phần tử, thêm số 8 thành 4 phần tử nên len(a) bằng 4.","t":"tin-cap3","l":"kho"},{"p":"Câu truy vấn: SELECT * FROM HOCSINH WHERE Diem >= 8 có tác dụng gì?","o":["Lấy mọi thông tin của những học sinh có điểm từ 8 trở lên","Xoá những học sinh có điểm dưới 8","Sắp xếp học sinh theo thứ tự điểm giảm dần","Thêm một học sinh mới vào bảng"],"a":"Lấy mọi thông tin của những học sinh có điểm từ 8 trở lên","h":"Chú ý mệnh đề WHERE — đó là điều kiện chọn bản ghi.","e":"SELECT * lấy tất cả các trường; WHERE Diem >= 8 chỉ giữ lại các bản ghi có điểm từ 8 trở lên.","t":"tin-cap3","l":"kho"},{"p":"Học máy (Machine Learning) là cách tiếp cận trong đó máy tính làm gì?","o":["Tự học từ dữ liệu để thực hiện nhiệm vụ tốt dần lên mà không cần lập trình chi tiết từng bước","Được con người viết sẵn mọi tình huống có thể xảy ra","Chỉ biết lưu trữ dữ liệu mà không xử lí","Hoạt động hoàn toàn không cần dữ liệu"],"a":"Tự học từ dữ liệu để thực hiện nhiệm vụ tốt dần lên mà không cần lập trình chi tiết từng bước","h":"Ví dụ: cho máy xem nhiều ảnh mèo, máy dần tự nhận ra mèo.","e":"Học máy cho phép máy tính rút ra quy luật từ dữ liệu mẫu để dự đoán, phân loại các dữ liệu mới.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Mã độc (phần mềm độc hại) có thể lây nhiễm vào máy tính qua con đường nào?","o":["Tệp đính kèm lạ, phần mềm không rõ nguồn gốc, USB đã nhiễm độc","Việc gõ bàn phím thường xuyên","Việc tắt máy đúng quy trình","Việc dùng chuột và màn hình chính hãng"],"a":"Tệp đính kèm lạ, phần mềm không rõ nguồn gốc, USB đã nhiễm độc","h":"Hãy cảnh giác với những tệp không rõ nguồn gốc được gửi tới.","e":"Mã độc thường ẩn trong tệp đính kèm lạ, phần mềm bẻ khoá/không rõ nguồn và thiết bị lưu trữ nhiễm độc.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Ứng dụng nào sau đây có sử dụng trí tuệ nhân tạo?","o":["Trợ lí ảo trên điện thoại nhận diện giọng nói để trả lời câu hỏi","Chiếc bút bi thông thường dùng để viết","Đồng hồ cơ đeo tay lên dây cót","Chiếc xe đạp không có thiết bị điện tử"],"a":"Trợ lí ảo trên điện thoại nhận diện giọng nói để trả lời câu hỏi","h":"Ứng dụng AI thường 'nghe, hiểu' hoặc 'nhìn, nhận biết' được.","e":"Trợ lí ảo dùng AI để nhận dạng tiếng nói và hiểu ngôn ngữ tự nhiên của người dùng.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Trong bệnh viện, cơ sở dữ liệu được ứng dụng chủ yếu để làm gì?","o":["Lưu trữ và tra cứu hồ sơ bệnh án của bệnh nhân","Trang trí phòng khám cho đẹp hơn","Thay thế hoàn toàn bác sĩ trong khám bệnh","In hoá đơn bán thuốc lá lẻ"],"a":"Lưu trữ và tra cứu hồ sơ bệnh án của bệnh nhân","h":"Nhờ CSDL, bác sĩ xem lại được tiền sử bệnh của bệnh nhân rất nhanh.","e":"CSDL giúp bệnh viện quản lí hồ sơ bệnh án, lịch khám, kết quả xét nghiệm một cách khoa học và tra cứu nhanh.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Khi sử dụng mạng xã hội, hành vi nào thể hiện văn hoá số đúng đắn?","o":["Kiểm chứng thông tin trước khi chia sẻ cho người khác","Chia sẻ ngay mọi tin giật gân chưa rõ đúng sai","Bình luận xúc phạm người không cùng quan điểm","Đăng công khai thông tin cá nhân của người khác"],"a":"Kiểm chứng thông tin trước khi chia sẻ cho người khác","h":"Tin giả lan nhanh phần lớn do người dùng chia sẻ vội vàng.","e":"Người dùng văn minh cần kiểm chứng nguồn tin, tránh lan truyền tin giả gây hại cho cộng đồng.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Phát biểu nào sau đây đúng về hạn chế của trí tuệ nhân tạo hiện nay?","o":["AI chưa thể thay thế hoàn toàn con người trong các công việc cần cảm xúc, kinh nghiệm sống và sáng tạo sâu sắc","AI luôn cho kết quả đúng tuyệt đối trong mọi trường hợp","AI hoạt động không cần bất kì dữ liệu nào","AI hiểu được mọi ngôn ngữ và văn hoá như con người"],"a":"AI chưa thể thay thế hoàn toàn con người trong các công việc cần cảm xúc, kinh nghiệm sống và sáng tạo sâu sắc","h":"AI rất mạnh ở xử lí dữ liệu nhưng còn yếu ở cảm xúc và kinh nghiệm sống.","e":"AI hiện nay mạnh trong các nhiệm vụ có dữ liệu rõ ràng, nhưng còn hạn chế về cảm xúc, kinh nghiệm và phán đoán như con người.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Xác thực hai yếu tố (mật khẩu kèm mã xác nhận gửi về điện thoại) giúp ích gì cho tài khoản trực tuyến?","o":["Tăng độ an toàn, kẻ xấu biết mật khẩu vẫn khó đăng nhập được","Giúp đăng nhập nhanh hơn không cần thao tác gì thêm","Giúp tài khoản không bao giờ bị quên mật khẩu","Giúp tăng dung lượng lưu trữ của tài khoản"],"a":"Tăng độ an toàn, kẻ xấu biết mật khẩu vẫn khó đăng nhập được","h":"Đây là thêm một 'lớp khoá' nữa ngoài mật khẩu.","e":"Xác thực hai yếu tố buộc người đăng nhập có thêm mã xác nhận, nên tài khoản an toàn hơn hẳn.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Người làm việc trong lĩnh vực tin học cần có phẩm chất nào sau đây?","o":["Tư duy logic, cẩn thận và luôn ham học hỏi công nghệ mới","Chỉ cần thuộc lòng một ngôn ngữ lập trình là đủ","Không cần làm việc nhóm hay giao tiếp với ai","Ngại thay đổi, chỉ dùng những gì đã quen"],"a":"Tư duy logic, cẩn thận và luôn ham học hỏi công nghệ mới","h":"Công nghệ thay đổi rất nhanh nên người làm tin học phải liên tục cập nhật.","e":"Tư duy logic, tính cẩn thận và tinh thần tự học là những phẩm chất quan trọng của nghề tin học.","t":"tin-cap3","l":"nhe-nhang"},{"p":"Điểm khác biệt cơ bản giữa học máy và lập trình truyền thống là gì?","o":["Học máy để máy tự rút ra quy luật từ dữ liệu, còn lập trình truyền thống do con người viết sẵn mọi quy tắc","Học máy không dùng đến máy tính","Lập trình truyền thống luôn cho kết quả nhanh hơn học máy","Học máy chỉ dùng cho trò chơi điện tử"],"a":"Học máy để máy tự rút ra quy luật từ dữ liệu, còn lập trình truyền thống do con người viết sẵn mọi quy tắc","h":"Một bên 'dạy bằng ví dụ', một bên 'viết luật chi tiết'.","e":"Trong lập trình truyền thống, con người định sẵn quy tắc; trong học máy, mô hình tự học quy luật từ dữ liệu mẫu.","t":"tin-cap3","l":"thu-thach"},{"p":"'Phần mềm độc hại' (malware) là tên gọi chung cho các chương trình như thế nào?","o":["Được tạo ra với mục đích xấu như đánh cắp dữ liệu, phá hoại hoặc chiếm quyền điều khiển hệ thống","Được cài sẵn theo máy để hỗ trợ người dùng","Dùng để tăng tốc độ mạng cho máy tính","Dùng để sao lưu dữ liệu an toàn"],"a":"Được tạo ra với mục đích xấu như đánh cắp dữ liệu, phá hoại hoặc chiếm quyền điều khiển hệ thống","h":"Virus, sâu máy tính, mã độc tống tiền đều thuộc nhóm này.","e":"Malware là các chương trình có hại như virus, worm, trojan, ransomware... gây tổn hại cho hệ thống và người dùng.","t":"tin-cap3","l":"thu-thach"},{"p":"Biện pháp nào sau đây giúp phòng tránh mã độc hiệu quả?","o":["Cài phần mềm diệt virus, cập nhật hệ điều hành và không mở tệp, đường liên kết lạ","Tắt mọi phần mềm bảo vệ để máy chạy nhẹ hơn","Mở thử mọi tệp đính kèm để kiểm tra nội dung","Dùng chung một mật khẩu đơn giản cho mọi tài khoản"],"a":"Cài phần mềm diệt virus, cập nhật hệ điều hành và không mở tệp, đường liên kết lạ","h":"Phòng bệnh hơn chữa bệnh — hãy nghĩ tới các thói quen an toàn hằng ngày.","e":"Kết hợp phần mềm diệt virus, cập nhật bản vá và thận trọng với tệp/link lạ là cách phòng tránh mã độc hiệu quả.","t":"tin-cap3","l":"thu-thach"},{"p":"Khi sử dụng kết quả do AI tạo ra (bài viết, hình ảnh), trách nhiệm của người dùng là gì?","o":["Kiểm tra lại độ tin cậy của kết quả và chịu trách nhiệm về nội dung mình sử dụng, chia sẻ","Cứ dùng và chia sẻ ngay vì AI luôn đúng","Không cần quan tâm vì lỗi là do AI chịu trách nhiệm","Chỉ cần ghi nguồn 'do AI làm' là đủ mọi trách nhiệm"],"a":"Kiểm tra lại độ tin cậy của kết quả và chịu trách nhiệm về nội dung mình sử dụng, chia sẻ","h":"AI có thể tạo ra thông tin sai trông rất thuyết phục.","e":"Kết quả AI có thể sai hoặc bịa đặt; người dùng phải kiểm chứng và chịu trách nhiệm về nội dung mình dùng.","t":"tin-cap3","l":"thu-thach"},{"p":"Việc ứng dụng cơ sở dữ liệu trong ngân hàng đem lại lợi ích gì nổi bật?","o":["Quản lí thông tin khách hàng, tài khoản và giao dịch chính xác, tra cứu nhanh chóng","Giúp ngân hàng không cần nhân viên nữa","Giúp khách hàng không cần nhớ số tài khoản khi giao dịch ở nhà","Tự động tăng số tiền trong tài khoản khách hàng"],"a":"Quản lí thông tin khách hàng, tài khoản và giao dịch chính xác, tra cứu nhanh chóng","h":"Mỗi ngày ngân hàng xử lí hàng triệu giao dịch — không thể quản lí bằng giấy tờ.","e":"CSDL giúp ngân hàng lưu trữ và xử lí lượng lớn dữ liệu khách hàng, giao dịch một cách chính xác, an toàn và tức thời.","t":"tin-cap3","l":"thu-thach"},{"p":"Một mô hình AI được huấn luyện gần như chỉ bằng ảnh mèo. Khi đưa ảnh chó vào, nó phân loại rất kém. Hiện tượng này cho thấy điều gì?","o":["Chất lượng của mô hình học máy phụ thuộc nhiều vào dữ liệu dùng để huấn luyện","Máy tính bị hỏng phần cứng","AI có thể tự hiểu mọi loài vật mà không cần học","Dữ liệu huấn luyện không ảnh hưởng gì tới kết quả của AI"],"a":"Chất lượng của mô hình học máy phụ thuộc nhiều vào dữ liệu dùng để huấn luyện","h":"Máy chỉ 'biết' những gì đã được học từ dữ liệu.","e":"Mô hình học máy chỉ làm tốt với dữ liệu tương tự dữ liệu huấn luyện; dữ liệu thiếu đa dạng khiến kết quả kém.","t":"tin-cap3","l":"kho"},{"p":"Bạn nhận được thư điện tử lạ giả danh ngân hàng, yêu cầu bấm vào đường liên kết để 'xác minh tài khoản kẻo bị khoá'. Cách xử lí đúng nhất là gì?","o":["Không bấm vào liên kết; tự truy cập trang web chính thức của ngân hàng hoặc gọi tổng đài để kiểm tra","Bấm ngay vào liên kết và nhập mật khẩu cho kịp thời hạn","Chuyển tiếp thư cho bạn bè để mọi người cùng xác minh","Trả lời thư và hỏi lại người gửi có phải ngân hàng thật không"],"a":"Không bấm vào liên kết; tự truy cập trang web chính thức của ngân hàng hoặc gọi tổng đài để kiểm tra","h":"Đây là chiêu lừa đảo 'phishing' rất phổ biến nhằm đánh cắp tài khoản.","e":"Thư giả mạo ngân hàng là hình thức lừa đảo phổ biến; cần liên hệ ngân hàng qua kênh chính thức thay vì làm theo liên kết trong thư.","t":"tin-cap3","l":"kho"}];